import { mkdir, rm } from 'node:fs/promises';
import { generateLogo } from './generate-logo.ts';
import { writeChanged } from './files.ts';
import { prepareKnowledge } from './guide-assets.ts';

const banner =
  '/* eslint-disable -- Generated bundle contains third-party code. Lint src/ and tools/ sources. */ /* Generated by bun run build. Do not edit. */';

async function bundle(options: Parameters<typeof Bun.build>[0]) {
  const result = await Bun.build(options);
  if (!result.success) throw new AggregateError(result.logs, 'Bun build failed');
  return result.outputs;
}

export async function buildBrowser() {
  await generateLogo();
  await mkdir('dist/client', { recursive: true });
  for (const [entry, filename] of [
    ['src/client/header.ts', 'header.js'],
    ['src/client/aria-entry.ts', 'aria-preview.js']
  ]) {
    const outputs = await bundle({
      entrypoints: [entry],
      target: 'browser',
      format: 'iife',
      minify: { whitespace: true, identifiers: true, syntax: false },
      banner
    });
    await writeChanged(`dist/client/${filename}`, new Uint8Array(await outputs[0].arrayBuffer()));
  }
  await Promise.all(
    ['style.css', 'aria.svg', 'favicon.svg'].map(async (file) =>
      writeChanged(`dist/client/${file}`, new Uint8Array(await Bun.file(file).arrayBuffer()))
    )
  );
  // Mintlify loads this generated copy from its content root.
  await writeChanged('header.js', await Bun.file('dist/client/header.js').text());
}

export async function buildRelease() {
  if (Bun.version !== '1.4.3') throw new Error('Release builds require Bun 1.4.3.');
  await rm('dist', { recursive: true, force: true });
  await buildBrowser();
  await prepareKnowledge();
  await mkdir('dist/server', { recursive: true });
  await bundle({
    entrypoints: [
      'src/server/aria-server.ts',
      'src/server/aria-preview.ts',
      'src/server/aria-runtime.ts'
    ],
    outdir: 'dist/server',
    target: 'bun',
    format: 'esm',
    sourcemap: 'external',
    naming: '[name].js',
    packages: 'bundle'
  });
  const files: Record<string, string> = {};
  for await (const name of new Bun.Glob('**/*').scan('dist')) {
    const file = Bun.file(`dist/${name}`);
    files[name] = new Bun.CryptoHasher('sha256').update(await file.arrayBuffer()).digest('hex');
  }
  await Bun.write(
    'dist/manifest.json',
    JSON.stringify({ runtime: `bun@${Bun.version}`, files }, null, 2) + '\n'
  );
  console.log('Built dist/client and dist/server release artifacts.');
}

if (import.meta.main) {
  if (process.argv.includes('--browser')) await buildBrowser();
  else await buildRelease();
}
